declare(strict_types=1);

if (PHP_SAPI !== "cli") { http_response_code(403); exit; }
$raiz = __DIR__;
$patches = [
    "mod/auth/Pagamento.php" => [
        ["RETIRO_MEIO_SEGURO_RECEBIMENTO_V1", "ICAgIHB1YmxpYyBmdW5jdGlvbiBhdHVhbGl6YXJSZWNlYmltZW50bygKICAgICAgICBpbnQgJGlkUGFnYW1lbnRvLAogICAgICAgIGFycmF5ICRkYWRvcwogICAgKTogYm9vbCB7", ""],
        ["RETIRO_MEIO_SEGURO_VALIDAR_MANUAL_V1", "ICAgICAgICAkdGhpcy0+dmFsaWRhclN0YXR1cygkc3RhdHVzKTsKICAgICAgICAkdGhpcy0+dmFsaWRhckZvcm1hUGFnYW1lbnRvKCRmb3JtYSk7CgogICAgICAgICRkYXRhUGFnYW1lbnRvID0gJHRoaXMtPm5vcm1hbGl6YXJEYXRhSG9yYSg=", ""],
        ["RETIRO_MEIO_SEGURO_PERSISTIR_ASAAS_V1", "ICAgICAgICAkZm9ybWEgPSB0cmltKChzdHJpbmcpICgkZGFkb3NbImZvcm1hUGFnYW1lbnRvIl0gPz8gJHBhZ2FtZW50b0F0dWFsWyJmb3JtYVBhZ2FtZW50byJdID8/ICJOYW9EZWZpbmlkbyIpKTsKICAgICAgICAkc3RhdHVzID0gdHJpbSgoc3RyaW5nKSAoJGRhZG9zWyJzdGF0dXMiXSA/PyAkcGFnYW1lbnRvQXR1YWxbInN0YXR1cyJdID8/ICJQZW5kZW50ZSIpKTs=", ""],
        ["RETIRO_MEIO_SEGURO_WEBHOOK_V1", "ICAgICAgICAkcGFnYW1lbnRvQXR1YWwgPSAkdGhpcy0+YnVzY2FyUG9yQXNhYXNQYXltZW50SWQoJGFzYWFzUGF5bWVudElkKTsKCiAgICAgICAgaWYgKCEkcGFnYW1lbnRvQXR1YWwpIHsKICAgICAgICAgICAgcmV0dXJuIGZhbHNlOwogICAgICAgIH0KCiAgICAgICAgJHRoaXMtPnZhbGlkYXJTdGF0dXMoJHN0YXR1cyk7", ""],
    ],
    "mod/services/AsaasPagamentoService.php" => [
        ["RETIRO_MEIO_SEGURO_GERAR_V1", "ICAgIHB1YmxpYyBmdW5jdGlvbiBnZXJhck91UmVjdXBlcmFyQ29icmFuY2EoaW50ICRpZFBhZ2FtZW50bywgc3RyaW5nICRmb3JtYSk6IGFycmF5CiAgICB7", ""],
        ["RETIRO_MEIO_SEGURO_GUARDA_GERAR_V1", "ICAgICAgICBpZiAoKGludCkgKCRwYWdhbWVudG9bImlkSW5zY3JpY2FvIl0gPz8gMCkgPD0gMCkgew==", "ICAgICAgICAvLyBSRVRJUk9fTUVJT19TRUdVUk9fR1VBUkRBX0dFUkFSX1YxCiAgICAgICAgUGFnYW1lbnRvTWVpb1NlZ3Vybzo6dmFsaWRhck9ubGluZSgkcGFnYW1lbnRvKTsKCiAgICAgICAgaWYgKChpbnQpICgkcGFnYW1lbnRvWyJpZEluc2NyaWNhbyJdID8/IDApIDw9IDApIHs="],
        ["RETIRO_MEIO_SEGURO_SINCRONIZAR_V1", "ICAgIHB1YmxpYyBmdW5jdGlvbiBzaW5jcm9uaXphckNvYnJhbmNhKGludCAkaWRQYWdhbWVudG8pOiBhcnJheQogICAgew==", ""],
        ["RETIRO_MEIO_SEGURO_GUARDA_SINCRONIZAR_V1", "ICAgICAgICAkaWRBc2FhcyA9IHRyaW0oKHN0cmluZykgKCRwYWdhbWVudG9bImFzYWFzUGF5bWVudElkIl0gPz8gIiIpKTsKCiAgICAgICAgaWYgKCRpZEFzYWFzID09PSAiIikgew==", "ICAgICAgICAvLyBSRVRJUk9fTUVJT19TRUdVUk9fR1VBUkRBX1NJTkNST05JWkFSX1YxCiAgICAgICAgUGFnYW1lbnRvTWVpb1NlZ3Vybzo6dmFsaWRhck9ubGluZSgkcGFnYW1lbnRvKTsKCiAgICAgICAgJGlkQXNhYXMgPSB0cmltKChzdHJpbmcpICgkcGFnYW1lbnRvWyJhc2Fhc1BheW1lbnRJZCJdID8/ICIiKSk7CgogICAgICAgIGlmICgkaWRBc2FhcyA9PT0gIiIpIHs="],
